1	//===--- A platform independent file data structure -------------*- C++ -*-===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	
9	#ifndef LLVM_LIBC_SRC___SUPPORT_FILE_FILE_H
10	#define LLVM_LIBC_SRC___SUPPORT_FILE_FILE_H
11	
12	#include "hdr/stdint_proxy.h"
13	#include "hdr/stdio_macros.h"
14	#include "hdr/types/off_t.h"
15	#include "hdr/types/wchar_t.h"
16	#include "hdr/types/wint_t.h"
17	#include "src/__support/CPP/new.h"
18	#include "src/__support/error_or.h"
19	#include "src/__support/macros/config.h"
20	#include "src/__support/macros/properties/architectures.h"
21	#include "src/__support/threads/mutex.h"
22	#include "src/__support/wchar/mbstate.h"
23	
24	#include <stddef.h>
25	
26	namespace LIBC_NAMESPACE_DECL {
27	
28	struct FileIOResult {
29	  size_t value;
30	  int error;
31	
32	  constexpr FileIOResult(size_t val) : value(val), error(0) {}
33	  constexpr FileIOResult(size_t val, int error) : value(val), error(error) {}
34	
35	  constexpr bool has_error() { return error != 0; }
36	
37	  constexpr operator size_t() { return value; }
38	};
39	
40	// This a generic base class to encapsulate a platform independent file data
41	// structure. Platform specific specializations should create a subclass as
42	// suitable for their platform.
43	class File {
44	public:
45	  static void add_file(File *f);
46	  static void remove_file(File *f);
47	  static File *get_first_file();
48	  static void lock_list();
49	  static void unlock_list();
50	
51	  static File *list_all;
52	  static Mutex list_lock;
53	
54	  File *get_next() const { return next; }
55	
56	  static constexpr size_t DEFAULT_BUFFER_SIZE = 1024;
57	
58	  enum class Orientation { UNORIENTED, BYTE, WIDE };
59	
60	  using LockFunc = void(File *);
61	  using UnlockFunc = void(File *);
62	
63	  using WriteFunc = FileIOResult(File *, const void *, size_t);
64	  using ReadFunc = FileIOResult(File *, void *, size_t);
65	  // The SeekFunc is expected to return the current offset of the external
66	  // file position indicator.
67	  using SeekFunc = ErrorOr<off_t>(File *, off_t, int);
68	  using CloseFunc = int(File *);
69	
70	  using ModeFlags = uint32_t;
71	
72	  // The three different types of flags below are to be used with '|' operator.
73	  // Their values correspond to mutually exclusive bits in a 32-bit unsigned
74	  // integer value. A flag set can include both READ and WRITE if the file
75	  // is opened in update mode (ie. if the file was opened with a '+' the mode
76	  // string.)
77	  enum class OpenMode : ModeFlags {
78	    READ = 0x1,
79	    WRITE = 0x2,
80	    APPEND = 0x4,
81	    PLUS = 0x8,
82	  };
83	
84	  // Denotes a file opened in binary mode (which is specified by including
85	  // the 'b' character in teh mode string.)
86	  enum class ContentType : ModeFlags {
87	    BINARY = 0x10,
88	  };
89	
90	  // Denotes a file to be created for writing.
91	  enum class CreateType : ModeFlags {
92	    EXCLUSIVE = 0x100,
93	  };
94	
95	private:
96	  enum class FileOp : uint8_t { NONE, READ, WRITE, SEEK };
97	
98	  // Platform specific functions which create new file objects should initialize
99	  // these fields suitably via the constructor. Typically, they should be simple
100	  // syscall wrappers for the corresponding functionality.
101	  WriteFunc *platform_write;
102	  ReadFunc *platform_read;
103	  SeekFunc *platform_seek;
104	  CloseFunc *platform_close;
105	
106	  Mutex mutex;
107	
108	  // For files which are readable, we should be able to support one ungetc
109	  // operation even if |buf| is nullptr. So, in the constructor of File, we
110	  // set |buf| to point to this buffer character. It needs to be at least 4
111	  // bytes so we can store a widechar.
112	  uint8_t ungetc_buf[4];
113	
114	  uint8_t *buf;   // Pointer to the stream buffer for buffered streams
115	  size_t bufsize; // Size of the buffer pointed to by |buf|.
116	
117	  // Buffering mode to used to buffer.
118	  int bufmode;
119	
120	  // If own_buf is true, the |buf| is owned by the stream and will be
121	  // free-ed when close method is called on the stream.
122	  bool own_buf;
123	
124	  // The mode in which the file was opened.
125	  ModeFlags mode;
126	
127	  // Current read or write pointer.
128	  size_t pos;
129	
130	  // Represents the previous operation that was performed.
131	  FileOp prev_op;
132	
133	  // When the buffer is used as a read buffer, read_limit is the upper limit
134	  // of the index to which the buffer can be read until.
135	  size_t read_limit;
136	
137	  bool eof;
138	  bool err;
139	
140	  Orientation orientation;
141	  internal::mbstate mbstate;
142	
143	  // This is a convenience RAII class to lock and unlock file objects.
144	  class FileLock {
145	    File *file;
146	
147	  public:
148	    explicit FileLock(File *f) : file(f) { file->lock(); }
149	
150	    ~FileLock() { file->unlock(); }
151	
152	    FileLock(const FileLock &) = delete;
153	    FileLock(FileLock &&) = delete;
154	  };
155	
156	protected:
157	  constexpr bool write_allowed() const {
158	    return mode & (static_cast<ModeFlags>(OpenMode::WRITE) |
159	                   static_cast<ModeFlags>(OpenMode::APPEND) |
160	                   static_cast<ModeFlags>(OpenMode::PLUS));
161	  }
162	
163	  constexpr bool read_allowed() const {
164	    return mode & (static_cast<ModeFlags>(OpenMode::READ) |
165	                   static_cast<ModeFlags>(OpenMode::PLUS));
166	  }
167	
168	public:
169	  // We want this constructor to be constexpr so that global file objects
170	  // like stdout do not require invocation of the constructor which can
171	  // potentially lead to static initialization order fiasco. Consequently,
172	  // we will assume that the |buffer| and |buffer_size| argument are
173	  // meaningful - that is, |buffer| is nullptr if and only if |buffer_size|
174	  // is zero. This way, we will not have to employ the semantics of
175	  // the set_buffer method and allocate a buffer.
176	  constexpr File(WriteFunc *wf, ReadFunc *rf, SeekFunc *sf, CloseFunc *cf,
177	                 uint8_t *buffer, size_t buffer_size, int buffer_mode,
178	                 bool owned, ModeFlags modeflags)
179	      : platform_write(wf), platform_read(rf), platform_seek(sf),
180	        platform_close(cf), mutex(/*timed=*/false, /*recursive=*/false,
181	                                  /*robust=*/false, /*pshared=*/false),
182	        ungetc_buf{}, buf(buffer), bufsize(buffer_size), bufmode(buffer_mode),
183	        own_buf(owned), mode(modeflags), pos(0), prev_op(FileOp::NONE),
184	        read_limit(0), eof(false), err(false),
185	        orientation(Orientation::UNORIENTED), mbstate(), prev(nullptr),
186	        next(nullptr) {
187	    adjust_buf();
188	  }
189	
190	  // Buffered write of |len| bytes from |data| without the file lock.
191	  FileIOResult write_unlocked(const void *data, size_t len);
192	
193	  // Buffered write of |len| bytes from |data| under the file lock.
194	  FileIOResult write(const void *data, size_t len) {
195	    FileLock l(this);
196	    return write_unlocked(data, len);
197	  }
198	
199	  // Buffered read of |len| bytes into |data| without the file lock.
200	  FileIOResult read_unlocked(void *data, size_t len);
201	
202	  // Buffered read of |len| bytes into |data| under the file lock.
203	  FileIOResult read(void *data, size_t len) {
204	    FileLock l(this);
205	    return read_unlocked(data, len);
206	  }
207	
208	  ErrorOr<int> seek(off_t offset, int whence);
209	
210	  ErrorOr<off_t> tell();
211	
212	  // If buffer has data written to it, flush it out. Does nothing if the
213	  // buffer is currently being used as a read buffer.
214	  int flush() {
215	    FileLock lock(this);
216	    return flush_unlocked();
217	  }
218	
219	  int flush_unlocked();
220	
221	  // Returns EOF on error and keeps the file unchanged.
222	  int ungetc_unlocked(int c);
223	
224	  int ungetc(int c) {
225	    FileLock lock(this);
226	    return ungetc_unlocked(c);
227	  }
228	
229	  FileIOResult write_unlocked(const wchar_t *ws, size_t len);
230	
231	  FileIOResult write(const wchar_t *ws, size_t len) {
232	    FileLock l(this);
233	    return write_unlocked(ws, len);
234	  }
235	
236	  FileIOResult read_unlocked(wchar_t *ws, size_t len);
237	
238	  FileIOResult read(wchar_t *ws, size_t len) {
239	    FileLock l(this);
240	    return read_unlocked(ws, len);
241	  }
242	
243	  ErrorOr<wint_t> ungetwc_unlocked(wint_t wc);
244	
245	  ErrorOr<wint_t> ungetwc(wint_t wc) {
246	    FileLock lock(this);
247	    return ungetwc_unlocked(wc);
248	  }
249	
250	  // Does the following:
251	  // 1. If in write mode, Write out any data present in the buffer.
252	  // 2. Call platform_close.
253	  // platform_close is expected to cleanup the complete file object.
254	  int close() {
255	    {
256	      FileLock lock(this);
257	      if (prev_op == FileOp::WRITE && pos > 0) {
258	        auto buf_result = platform_write(this, buf, pos);
259	        if (buf_result.has_error() || buf_result.value < pos) {
260	          err = true;
261	          return buf_result.error;
262	        }
263	      }
264	    }
265	
266	    // If we own the buffer, delete it before calling the platform close
267	    // implementation. The platform close should not need to access the buffer
268	    // and we need to clean it up before the entire structure is removed.
269	    if (own_buf)
270	      delete buf;
271	
272	    // Platform close is expected to cleanup the file data structure which
273	    // includes the file mutex. Hence, we call platform_close after releasing
274	    // the file lock. Another thread doing file operations while a thread is
275	    // closing the file is undefined behavior as per POSIX.
276	    return platform_close(this);
277	  }
278	
279	  // Sets the internal buffer to |buffer| with buffering mode |mode|.
280	  // |size| is the size of |buffer|. If |size| is non-zero, but |buffer|
281	  // is nullptr, then a buffer owned by this file will be allocated.
282	  // Else, |buffer| will not be owned by this file.
283	  //
284	  // Will return zero on success, or an error value on failure. Will fail
285	  // if:
286	  //   1. |buffer| is not a nullptr but |size| is zero.
287	  //   2. |buffer_mode| is not one of _IOLBF, IOFBF or _IONBF.
288	  //   3. If an allocation was required but the allocation failed.
289	  // For cases 1 and 2, the error returned in EINVAL. For case 3, error returned
290	  // is ENOMEM.
291	  int set_buffer(void *buffer, size_t size, int buffer_mode);
292	
293	  void lock() { mutex.lock(); }
294	  void unlock() { mutex.unlock(); }
295	
296	  bool error_unlocked() const { return err; }
297	
298	  bool error() {
299	    FileLock l(this);
300	    return error_unlocked();
301	  }
302	
303	  // TODO: https://github.com/llvm/llvm-project/issues/172302
304	  // MacOS defines clearerr_unlocked as a macro. While pre-processing, the
305	  // identifier below is substituted for the definition in the SDK, which leads
306	  // to compile time errors due to ill-formed statements. This is a workaround
307	  // for the pre-processor.
308	#pragma push_macro("clearerr_unlocked")
309	#undef clearerr_unlocked
310	  void clearerr_unlocked() { err = false; }
311	#pragma pop_macro("clearerr_unlocked")
312	
313	  void clearerr() {
314	    FileLock l(this);
315	    clearerr_unlocked();
316	  }
317	
318	  bool iseof_unlocked() { return eof; }
319	
320	  bool iseof() {
321	    FileLock l(this);
322	    return iseof_unlocked();
323	  }
324	
325	  Orientation get_orientation_unlocked() const { return orientation; }
326	
327	  Orientation get_orientation() {
328	    FileLock l(this);
329	    return get_orientation_unlocked();
330	  }
331	
332	  Orientation try_set_orientation_unlocked(Orientation o) {
333	    if (orientation == Orientation::UNORIENTED)
334	      orientation = o;
335	    return orientation;
336	  }
337	
338	  Orientation try_set_orientation(Orientation o) {
339	    FileLock l(this);
340	    return try_set_orientation_unlocked(o);
341	  }
342	
343	  // Returns an bit map of flags corresponding to enumerations of
344	  // OpenMode, ContentType and CreateType.
345	  static ModeFlags mode_flags(const char *mode);
346	
347	private:
348	  FileIOResult write_unlocked_impl(const void *data, size_t len);
349	  FileIOResult read_unlocked_impl(void *data, size_t len);
350	
351	  FileIOResult write_unlocked_lbf(const uint8_t *data, size_t len);
352	  FileIOResult write_unlocked_fbf(const uint8_t *data, size_t len);
353	  FileIOResult write_unlocked_nbf(const uint8_t *data, size_t len);
354	
355	  FileIOResult read_unlocked_fbf(uint8_t *data, size_t len);
356	  FileIOResult read_unlocked_nbf(uint8_t *data, size_t len);
357	  size_t copy_data_from_buf(uint8_t *data, size_t len);
358	
359	  constexpr void adjust_buf() {
360	    if (read_allowed() && (buf == nullptr || bufsize == 0)) {
361	      // We should allow atleast one ungetc operation.
362	      // This might give an impression that a buffer will be used even when
363	      // the user does not want a buffer. But, that will not be the case.
364	      // For reading, the buffering does not come into play. For writing, let
365	      // us take up the three different kinds of buffering separately:
366	      // 1. If user wants _IOFBF but gives a zero buffer, buffering still
367	      //    happens in the OS layer until the user flushes. So, from the user's
368	      //    point of view, this single byte buffer does not affect their
369	      //    experience.
370	      // 2. If user wants _IOLBF but gives a zero buffer, the reasoning is
371	      //    very similar to the _IOFBF case.
372	      // 3. If user wants _IONBF, then the buffer is ignored for writing.
373	      // So, all of the above cases, having a single ungetc buffer does not
374	      // affect the behavior experienced by the user.
375	      buf = ungetc_buf;
376	      bufsize = sizeof(ungetc_buf);
377	      own_buf = false; // We shouldn't call free on |buf| when closing the file.
378	    }
379	  }
380	
381	  File *prev;
382	  File *next;
383	};
384	
385	// The implementation of this function is provided by the platform_file
386	// library.
387	ErrorOr<File *> openfile(const char *path, const char *mode);
388	
389	// The platform_file library should implement it if it relevant for that
390	// platform.
391	int get_fileno(File *f);
392	
393	} // namespace LIBC_NAMESPACE_DECL
394	
395	#endif // LLVM_LIBC_SRC___SUPPORT_FILE_FILE_H
396

