59	FileIOResult File::write_unlocked(const void *data, size_t len) {
60	  switch (orientation) {
61	  case Orientation::WIDE:
62	    err = true;
63	    return {0, EINVAL};
64	  case Orientation::UNORIENTED:
65	    orientation = Orientation::BYTE;
66	    break;
67	  case Orientation::BYTE:
68	    break;
69	  }
70	  return write_unlocked_impl(data, len);
71	}
72	
73	FileIOResult File::write_unlocked_impl(const void *data, size_t len) {
74	  if (!write_allowed()) {
75	    err = true;
76	    return {0, EBADF};
77	  }
78	
79	  prev_op = FileOp::WRITE;
80	
81	  if (bufmode == _IONBF) { // unbuffered.
82	    size_t ret_val =
83	        write_unlocked_nbf(static_cast<const uint8_t *>(data), len);
84	    flush_unlocked();
85	    return ret_val;
86	  }
87	  if (bufmode == _IOFBF) // fully buffered
88	    return write_unlocked_fbf(static_cast<const uint8_t *>(data), len);
89	  return write_unlocked_lbf(static_cast<const uint8_t *>(data),
90	                            len); // line buffered
91	}
92	
93	FileIOResult File::write_unlocked_nbf(const uint8_t *data, size_t len) {
94	  if (pos > 0) { // If the buffer is not empty
95	    // Flush the buffer
96	    const size_t write_size = pos;
97	    FileIOResult write_result = platform_write(this, buf, write_size);
98	    pos = 0; // Buffer is now empty so reset pos to the beginning.
99	    // If less bytes were written than expected, then an error occurred.
100	    if (write_result < write_size) {
101	      err = true;
102	      // No bytes from data were written, so return 0.
103	      return {0, write_result.error};
104	    }
105	  }
106	
107	  FileIOResult write_result = platform_write(this, data, len);
108	  if (write_result < len)
109	    err = true;
110	  return write_result;
111	}
112	
113	FileIOResult File::write_unlocked_fbf(const uint8_t *data, size_t len) {
114	  const size_t init_pos = pos;
115	  const size_t bufspace = bufsize - pos;
116	
117	  // If data is too large to be buffered at all, then just write it unbuffered.
118	  if (len > bufspace + bufsize)
119	    return write_unlocked_nbf(data, len);
120	
121	  // we split |data| (conceptually) using the split point. Then we handle the
122	  // two pieces separately.
123	  const size_t split_point = len < bufspace ? len : bufspace;
124	
125	  // The primary piece is the piece of |data| we want to write to the buffer
126	  // before flushing. It will always fit into the buffer, since the split point
127	  // is defined as being min(len, bufspace), and it will always exist if len is
128	  // non-zero.
129	  cpp::span<const uint8_t> primary(data, split_point);
130	
131	  // The second piece is the remainder of |data|. It is written to the buffer if
132	  // it fits, or written directly to the output if it doesn't. If the primary
133	  // piece fits entirely in the buffer, the remainder may be nothing.
134	  cpp::span<const uint8_t> remainder(
135	      static_cast<const uint8_t *>(data) + split_point, len - split_point);
136	
137	  cpp::span<uint8_t> bufref(static_cast<uint8_t *>(buf), bufsize);
138	
139	  // Copy the first piece into the buffer.
140	  inline_memcpy(bufref.data() + pos, primary.data(), primary.size());
141	  pos += primary.size();
142	
143	  // If there is no remainder, we can return early, since the first piece has
144	  // fit completely into the buffer.
145	  if (remainder.size() == 0)
146	    return len;
147	
148	  // We need to flush the buffer now, since there is still data and the buffer
149	  // is full.
150	  const size_t write_size = pos;
151	
152	  FileIOResult buf_result = platform_write(this, buf, write_size);
153	  size_t bytes_written = buf_result.value;
154	
155	  pos = 0; // Buffer is now empty so reset pos to the beginning.
156	  // If less bytes were written than expected, then an error occurred. Return
157	  // the number of bytes that have been written from |data|.
158	  if (buf_result.has_error() || bytes_written < write_size) {
159	    err = true;
160	    return {bytes_written <= init_pos ? 0 : bytes_written - init_pos,
161	            buf_result.error};
162	  }
163	
164	  // The second piece is handled basically the same as the first, although we
165	  // know that if the second piece has data in it then the buffer has been
166	  // flushed, meaning that pos is always 0.
167	  if (remainder.size() < bufsize) {
168	    inline_memcpy(bufref.data(), remainder.data(), remainder.size());
169	    pos = remainder.size();
170	  } else {
171	
172	    FileIOResult result =
173	        platform_write(this, remainder.data(), remainder.size());
174	    bytes_written = result.value;
175	
176	    // If less bytes were written than expected, then an error occurred. Return
177	    // the number of bytes that have been written from |data|.
178	    if (result.has_error() || bytes_written < remainder.size()) {
179	      err = true;
180	      return {primary.size() + bytes_written, result.error};
181	    }
182	  }
183	
184	  return len;
185	}
