187	FileIOResult File::write_unlocked_lbf(const uint8_t *data, size_t len) {
188	  constexpr uint8_t NEWLINE_CHAR = '\n';
189	  size_t last_newline = len;
190	  for (size_t i = len; i >= 1; --i) {
191	    if (data[i - 1] == NEWLINE_CHAR) {
192	      last_newline = i - 1;
193	      break;
194	    }
195	  }
196	
197	  // If there is no newline, treat this as fully buffered.
198	  if (last_newline == len) {
199	    return write_unlocked_fbf(data, len);
200	  }
201	
202	  // we split |data| (conceptually) using the split point. Then we handle the
203	  // two pieces separately.
204	  const size_t split_point = last_newline + 1;
205	
206	  // The primary piece is everything in |data| up to the newline. It's written
207	  // unbuffered to the output.
208	  cpp::span<const uint8_t> primary(data, split_point);
209	
210	  // The second piece is the remainder of |data|. It is written fully buffered,
211	  // meaning it may stay in the buffer if it fits.
212	  cpp::span<const uint8_t> remainder(
213	      static_cast<const uint8_t *>(data) + split_point, len - split_point);
214	
215	  size_t written = 0;
216	
217	  written = write_unlocked_nbf(primary.data(), primary.size());
218	  if (written < primary.size()) {
219	    err = true;
220	    return written;
221	  }
222	
223	  flush_unlocked();
224	
225	  written += write_unlocked_fbf(remainder.data(), remainder.size());
226	  if (written < len) {
227	    err = true;
228	    return written;
229	  }
230	
231	  return len;
232	}
