235	  switch (orientation) {
236	  case Orientation::WIDE:
237	    err = true;
238	    return {0, EINVAL};
239	  case Orientation::UNORIENTED:
240	    orientation = Orientation::BYTE;
241	    break;
242	  case Orientation::BYTE:
