248	FileIOResult File::read_unlocked_impl(void *data, size_t len) {
249	  if (!read_allowed()) {
250	    err = true;
251	    return {0, EBADF};
252	  }
253	
254	  prev_op = FileOp::READ;
255	
256	  if (bufmode == _IONBF) { // unbuffered.
257	    return read_unlocked_nbf(static_cast<uint8_t *>(data), len);
258	  } else if (bufmode == _IOFBF) { // fully buffered
259	    return read_unlocked_fbf(static_cast<uint8_t *>(data), len);
260	  } else /*if (bufmode == _IOLBF) */ { // line buffered
261	    // There is no line buffered mode for read. Use fully buffered instead.
262	    return read_unlocked_fbf(static_cast<uint8_t *>(data), len);
263	  }
264	}
