266	size_t File::copy_data_from_buf(uint8_t *data, size_t len) {
267	  cpp::span<uint8_t> bufref(static_cast<uint8_t *>(buf), bufsize);
268	  cpp::span<uint8_t> dataref(static_cast<uint8_t *>(data), len);
269	
270	  // Because read_limit is always greater than equal to pos,
271	  // available_data is never a wrapped around value.
272	  size_t available_data = read_limit - pos;
273	  if (len <= available_data) {
274	    inline_memcpy(dataref.data(), bufref.data() + pos, len);
275	    pos += len;
276	    return len;
277	  }
278	
279	  // Copy all of the available data.
280	  inline_memcpy(dataref.data(), bufref.data() + pos, available_data);
281	  read_limit = pos = 0; // Reset the pointers.
282	
283	  return available_data;
284	}
285	
286	FileIOResult File::read_unlocked_fbf(uint8_t *data, size_t len) {
287	  // Read data from the buffer first.
288	  size_t available_data = copy_data_from_buf(data, len);
289	  if (available_data == len)
290	    return available_data;
291	
292	  // Update the dataref to reflect that fact that we have already
293	  // copied |available_data| into |data|.
294	  size_t to_fetch = len - available_data;
295	  cpp::span<uint8_t> dataref(static_cast<uint8_t *>(data) + available_data,
296	                             to_fetch);
297	
298	  if (to_fetch > bufsize) {
299	    FileIOResult result = platform_read(this, dataref.data(), to_fetch);
300	    size_t fetched_size = result.value;
301	    if (result.has_error() || fetched_size < to_fetch) {
302	      if (!result.has_error())
303	        eof = true;
304	      else
305	        err = true;
306	      return {available_data + fetched_size, result.error};
307	    }
308	    return len;
309	  }
310	
311	  // Fetch and buffer another buffer worth of data.
312	  FileIOResult result = platform_read(this, buf, bufsize);
313	  size_t fetched_size = result.value;
314	  read_limit += fetched_size;
315	  size_t transfer_size = fetched_size >= to_fetch ? to_fetch : fetched_size;
316	  inline_memcpy(dataref.data(), buf, transfer_size);
317	  pos += transfer_size;
318	  if (result.has_error() || fetched_size < to_fetch) {
319	    if (!result.has_error())
320	      eof = true;
321	    else
322	      err = true;
323	  }
324	  return {transfer_size + available_data, result.error};
325	}
326	
327	FileIOResult File::read_unlocked_nbf(uint8_t *data, size_t len) {
328	  // Check whether there is a character in the ungetc buffer.
329	  size_t available_data = copy_data_from_buf(data, len);
330	  if (available_data == len)
331	    return available_data;
332	
333	  // Directly copy the data into |data|.
334	  cpp::span<uint8_t> dataref(static_cast<uint8_t *>(data) + available_data,
335	                             len - available_data);
336	  FileIOResult result = platform_read(this, dataref.data(), dataref.size());
337	
338	  if (result.has_error() || result < dataref.size()) {
339	    if (!result.has_error())
340	      eof = true;
341	    else
342	      err = true;
343	  }
344	  return {result + available_data, result.error};
345	}
346	
347	int File::ungetc_unlocked(int c) {
348	  // There is no meaning to unget if:
349	  // 1. You are trying to push back EOF.
350	  // 2. Read operations are not allowed on this file.
351	  // 3. The previous operation was a write operation.
352	  if (c == EOF || !read_allowed() || (prev_op == FileOp::WRITE))
353	    return EOF;
354	
355	  switch (orientation) {
356	  case Orientation::WIDE:
357	    err = true;
358	    return EOF;
359	  case Orientation::UNORIENTED:
360	    orientation = Orientation::BYTE;
361	    break;
362	  case Orientation::BYTE:
363	    break;
364	  }
365	
366	  cpp::span<uint8_t> bufref(static_cast<uint8_t *>(buf), bufsize);
367	  if (read_limit == 0) {
368	    // If |read_limit| is zero, it can mean three things:
369	    //   a. This file was just created.
370	    //   b. The previous operation was a seek operation.
371	    //   c. The previous operation was a read operation which emptied
372	    //      the buffer.
373	    // For all the above cases, we simply write |c| at the beginning
374	    // of the buffer and bump |read_limit|. Note that |pos| will also
375	    // be zero in this case, so we don't need to adjust it.
376	    bufref[0] = static_cast<unsigned char>(c);
377	    ++read_limit;
378	  } else {
379	    // If |read_limit| is non-zero, it means that there is data in the buffer
380	    // from a previous read operation. Which would also mean that |pos| is not
381	    // zero. So, we decrement |pos| and write |c| in to the buffer at the new
382	    // |pos|. If too many ungetc operations are performed without reads, it
383	    // can lead to (pos == 0 but read_limit != 0). We will just error out in
384	    // such a case.
385	    if (pos == 0)
386	      return EOF;
387	    --pos;
388	    bufref[pos] = static_cast<unsigned char>(c);
389	  }
390	
391	  eof = false; // There is atleast one character that can be read now.
392	  err = false; // This operation was a success.
393	  return c;
394	}
395	
396	ErrorOr<int> File::seek(off_t offset, int whence) {
397	  FileLock lock(this);
398	  if (prev_op == FileOp::WRITE && pos > 0) {
399	
400	    FileIOResult buf_result = platform_write(this, buf, pos);
401	    if (buf_result.has_error() || buf_result.value < pos) {
402	      err = true;
403	      return Error(buf_result.error);
404	    }
405	  } else if (prev_op == FileOp::READ && whence == SEEK_CUR) {
406	    // More data could have been read out from the platform file than was
407	    // required. So, we have to adjust the offset we pass to platform seek
408	    // function. Note that read_limit >= pos is always true.
409	    offset -= (read_limit - pos);
410	  }
411	  auto result = platform_seek(this, offset, whence);
412	  if (!result.has_value())
413	    return Error(result.error());
414	
415	  pos = read_limit = 0;
416	  prev_op = FileOp::SEEK;
417	  // Reset the eof flag as a seek might move the file position to some place
418	  // readable.
419	  eof = false;
420	  if (orientation == Orientation::WIDE ||
421	      orientation == Orientation::UNORIENTED)
422	    mbstate = internal::mbstate();
423	
424	  return 0;
425	}
426	
427	ErrorOr<off_t> File::tell() {
428	  FileLock lock(this);
429	  auto seek_target = eof ? SEEK_END : SEEK_CUR;
430	  auto result = platform_seek(this, 0, seek_target);
431	  if (!result.has_value() || result.value() < 0)
432	    return Error(result.error());
433	  off_t platform_offset = result.value();
434	  if (prev_op == FileOp::READ)
435	    return platform_offset - (read_limit - pos);
436	  if (prev_op == FileOp::WRITE)
437	    return platform_offset + pos;
438	  return platform_offset;
439	}
440	
441	int File::flush_unlocked() {
442	  if (prev_op == FileOp::WRITE && pos > 0) {
443	    FileIOResult buf_result = platform_write(this, buf, pos);
444	    if (buf_result.has_error() || buf_result.value < pos) {
445	      err = true;
446	      return buf_result.error;
447	    }
448	    pos = 0;
449	  } else if (prev_op == FileOp::READ) {
450	    if (read_limit > pos) {
451	      if (!platform_seek(this, -static_cast<off_t>(read_limit - pos), SEEK_CUR)
452	               .has_value()) {
453	        // We ignore seek errors for non-seekable files (like pipes) as per
454	        // POSIX.
455	      }
456	    }
457	    pos = read_limit = 0;
458	  }
459	  return 0;
460	}
461	
462	int File::set_buffer(void *buffer, size_t size, int buffer_mode) {
463	  // We do not need to lock the file as this method should be called before
464	  // other operations are performed on the file.
465	  if (buffer != nullptr && size == 0)
466	    return EINVAL;
467	
468	  switch (buffer_mode) {
469	  case _IOFBF:
470	  case _IOLBF:
471	  case _IONBF:
472	    break;
473	  default:
474	    return EINVAL;
475	  }
476	
477	  if (buffer == nullptr && size != 0 && buffer_mode != _IONBF) {
478	    // We exclude the case of buffer_mode == _IONBF in this branch
479	    // because we don't need to allocate buffer in such a case.
480	    if (own_buf) {
481	      // This is one of the places where a C allocation function is used
482	      // as C++ does not have an equivalent of realloc.
483	      buf = reinterpret_cast<uint8_t *>(realloc(buf, size));
484	      if (buf == nullptr)
485	        return ENOMEM;
486	    } else {
487	      AllocChecker ac;
488	      buf = new (ac) uint8_t[size];
489	      if (!ac)
490	        return ENOMEM;
491	      own_buf = true;
492	    }
493	    bufsize = size;
494	    // TODO: Handle allocation failures.
495	  } else {
496	    if (own_buf)
497	      delete buf;
498	    if (buffer_mode != _IONBF) {
499	      buf = static_cast<uint8_t *>(buffer);
500	      bufsize = size;
501	    } else {
502	      // We don't need any buffer.
503	      buf = nullptr;
504	      bufsize = 0;
505	    }
506	    own_buf = false;
507	  }
508	  bufmode = buffer_mode;
509	  adjust_buf();
510	  return 0;
511	}
512	
513	File::ModeFlags File::mode_flags(const char *mode) {
514	  // First character in |mode| should be 'a', 'r' or 'w'.
515	  if (*mode != 'a' && *mode != 'r' && *mode != 'w')
516	    return 0;
517	
518	  // There should be exaclty one main mode ('a', 'r' or 'w') character.
519	  // If there are more than one main mode characters listed, then
520	  // we will consider |mode| as incorrect and return 0;
521	  int main_mode_count = 0;
522	
523	  ModeFlags flags = 0;
524	  for (; *mode != '\0'; ++mode) {
525	    switch (*mode) {
526	    case 'r':
527	      flags |= static_cast<ModeFlags>(OpenMode::READ);
528	      ++main_mode_count;
529	      break;
530	    case 'w':
531	      flags |= static_cast<ModeFlags>(OpenMode::WRITE);
532	      ++main_mode_count;
533	      break;
534	    case '+':
535	      flags |= static_cast<ModeFlags>(OpenMode::PLUS);
536	      break;
537	    case 'b':
538	      flags |= static_cast<ModeFlags>(ContentType::BINARY);
539	      break;
540	    case 'a':
541	      flags |= static_cast<ModeFlags>(OpenMode::APPEND);
542	      ++main_mode_count;
543	      break;
544	    case 'x':
545	      flags |= static_cast<ModeFlags>(CreateType::EXCLUSIVE);
546	      break;
547	    default:
548	      return 0;
549	    }
550	  }
551	
552	  if (main_mode_count != 1)
553	    return 0;
554	
555	  return flags;
556	}
557	
558	FileIOResult File::write_unlocked(const wchar_t *ws, size_t len) {
559	  switch (orientation) {
560	  case Orientation::BYTE:
561	    err = true;
562	    return {0, EINVAL};
563	  case Orientation::UNORIENTED:
564	    orientation = Orientation::WIDE;
565	    break;
566	  case Orientation::WIDE:
567	    break;
568	  }
569	
570	  size_t written = 0;
571	  for (size_t i = 0; i < len; ++i) {
572	    internal::CharacterConverter cr(&mbstate);
573	    int push_err = cr.push(static_cast<char32_t>(ws[i]));
574	    if (push_err != 0) {
575	      err = true;
576	      return {written, push_err};
577	    }
578	    // buffer the whole wchar to save on calls to write.
579	    char buffer[4];
580	    size_t char_size = 0;
581	    while (!cr.isEmpty()) {
582	      auto pop_res = cr.pop<char8_t>();
583	      if (!pop_res.has_value()) {
584	        err = true;
585	        return {written, pop_res.error()};
586	      }
587	      char8_t byte = pop_res.value();
588	      buffer[char_size] = byte;
589	      ++char_size;
590	    }
591	    auto write_res = write_unlocked_impl(buffer, char_size);
592	    if (write_res.has_error())
593	      return {written, write_res.error};
594	    if (write_res.value < char_size) {
595	      err = true;
596	      return {written, EIO};
597	    }
598	    ++written;
599	  }
600	  return {written, 0};
601	}
602	
603	FileIOResult File::read_unlocked(wchar_t *ws, size_t len) {
604	  switch (orientation) {
605	  case Orientation::BYTE:
606	    err = true;
607	    return {0, EINVAL};
608	  case Orientation::UNORIENTED:
609	    orientation = Orientation::WIDE;
610	    break;
611	  case Orientation::WIDE:
612	    break;
613	  }
614	
615	  size_t read_count = 0;
616	  for (size_t i = 0; i < len; ++i) {
617	    internal::CharacterConverter cr(&mbstate);
618	    while (!cr.isFull()) {
619	      uint8_t byte;
620	      auto read_res = read_unlocked_impl(&byte, 1);
621	      if (read_res.has_error())
622	        return {read_count, read_res.error};
623	      if (read_res.value == 0) { // EOF
624	        if (cr.isEmpty())
625	          return {read_count, 0};
626	        err = true;
627	        return {read_count, EILSEQ}; // Incomplete character at EOF
628	      }
629	      int push_err = cr.push(static_cast<char8_t>(byte));
630	      if (push_err != 0) {
631	        err = true;
632	        return {read_count, push_err};
633	      }
634	    }
635	    auto pop_res = cr.pop<char32_t>();
636	    if (!pop_res.has_value()) {
637	      err = true;
638	      return {read_count, pop_res.error()};
639	    }
640	    ws[i] = static_cast<wchar_t>(pop_res.value());
641	    ++read_count;
642	  }
643	  return {read_count, 0};
644	}
645	
646	ErrorOr<wint_t> File::ungetwc_unlocked(wint_t wc) {
647	  // There is no meaning to unget if:
648	  // 1. You are trying to push back EOF.
649	  // 2. Read operations are not allowed on this file.
650	  // 3. The previous operation was a write operation.
651	  if (wc == WEOF || !read_allowed() || (prev_op == FileOp::WRITE))
652	    return WEOF;
653	  switch (orientation) {
654	  case Orientation::BYTE:
655	    err = true;
656	    return WEOF;
657	  case Orientation::UNORIENTED:
658	    orientation = Orientation::WIDE;
659	    break;
660	  case Orientation::WIDE:
661	    break;
662	  }
663	
664	  char mb_buf[4];
665	  auto result = internal::wcrtomb(mb_buf, static_cast<wchar_t>(wc), &mbstate);
666	  if (!result.has_value())
667	    return Error(result.error());
668	
669	  size_t n = result.value();
670	
671	  if (read_limit == 0) {
672	    if (n > bufsize)
673	      return WEOF;
674	
675	    for (size_t i = 0; i < n; ++i)
676	      buf[i] = static_cast<uint8_t>(mb_buf[i]);
677	
678	    read_limit = n;
679	    pos = 0;
680	  } else {
681	    if (pos < n)
682	      return WEOF;
683	    pos -= n;
684	    for (size_t i = 0; i < n; ++i)
685	      buf[pos + i] = static_cast<uint8_t>(mb_buf[i]);
686	  }
687	  eof = false;
688	  err = false;
689	  return wc;
690	}
691	
692	} // namespace LIBC_NAMESPACE_DECL
